#define iterations 13
#define formuparam 0.53

#define volsteps 22
#define stepsize 0.1

#define zoom   0.800
#define tile   0.720
#define speed  0.000 

#define brightness 0.0015
#define darkmatter 0.300
#define distfading 0.730
#define saturation 0.850


#define PI 3.1415926538
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float gradientNoise(vec2 p) {
    // Grid cell coordinates
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Interpolation weights (smoothstep for smooth interpolation)
    vec2 u = f * f * (3.0 - 2.0 * f);

    // Hash the corners of the cell
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));

    // Interpolate the values
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}
float fbm( in vec2 x)
{    
	float H = 1.;
	int numOctaves = 4;
    float G = exp2(-H);
    float f = 1.0;
    float a = 1.0;
    float t = 0.0;
    float tenCycle = iTime*0.;
    float fiveCycle = 5. * (sin(2. * PI * iTime/5.) + 1.)/.5;
    vec2 offset = vec2(tenCycle, fiveCycle);
    for( int i=0; i<numOctaves; i++ )
    {
        t += a*gradientNoise(f*x + offset*.1);
        f *= 2.0;
        a *= G;
    }
    return t;
}

vec3 palette(float t) {
	vec3 a = vec3(0.4); // Brightness
	vec3 b = vec3(0.5); // Contrast
	vec3 c = vec3(0.3, 0.3, 0.75); // Color change speed
	vec3 d = vec3(0.6, 0.4, 0.7); // Offset

	return a + b * cos(PI * 2. * (c * t + d));
}

float pattern(vec2 p) {
	vec2 q = vec2(fbm(p), fbm(p + vec2(5.2, 1.3)));

	vec2 r = vec2(fbm(p + 4. * q + vec2(1.8, 4.5)), fbm(p + 4. * q + vec2(5.8, 2.0)));

	return fbm(p + 4. * r);
}
void mainVR( out vec4 fragColor, in vec2 fragCoord, in vec3 ro, in vec3 rd )
{
	//get coords and direction
	vec3 dir=rd;
	vec3 from=ro;

	//volumetric rendering
	float s=0.1,fade=1.;
	vec3 v=vec3(0.);
	for (int r=0; r<volsteps; r++) {
		vec3 p=from+s*dir*.5;
		p = abs(vec3(tile)-mod(p,vec3(tile*2.))); // tiling fold
		float pa,a=pa=0.;
		for (int i=0; i<iterations; i++) { 
			p=abs(p)/dot(p,p)-formuparam;
            p.xy*=mat2(cos(iTime*0.05),sin(iTime*0.05),-sin(iTime*0.05), cos(iTime*0.05));// the magic formula
			a+=abs(length(p)-pa); // absolute sum of average change
			pa=length(p);
		}
		float dm=max(0.,darkmatter-a*a*.001); //dark matter
		a*=a*a; // add contrast
		if (r>6) fade*=1.2-dm; // dark matter, don't render near
		//v+=vec3(dm,dm*.5,0.);
		v+=fade;
		v+=vec3(s,s*s,s*s*s*s)*a*brightness*fade; // coloring based on distance
		fade*=distfading; // distance fading
		s+=stepsize;
	}
	v=mix(vec3(length(v)),v,saturation); //color adjust
	fragColor = vec4(v*.03,1.);	
}
#define time iTime

#define Pi2 (Pi*2.)
#define resolution iResolution

uniform sampler2D tex;

vec2 Reflect(vec2 uv, float angle) {
	vec2 N = vec2(sin(angle), cos(angle));
	return N*min(0., dot(uv, N))*2.;
}

mat2 rot(float angle) {
	return mat2(cos(angle),-sin(angle),sin(angle),cos(angle));
}

float remap(float a1, float a2, float b1, float b2, float x) {
	return ((x-a1)/(a2-a1)) * (b2-b1) + b1;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	//get coords and direction
	vec2 uv=fragCoord.xy/iResolution.xy-.5;
      vec2 uv2 = gl_FragCoord.xy/iResolution.y*10.;
	uv.y*=iResolution.y/iResolution.x;
	vec3 dir=vec3(uv*zoom,1.);


  	//uv.x = abs(uv.x);
	vec3 col = vec3(0.);


	uv *= rot(time/10.*3.1415);
	// 2nd
	float angle = -1.13;
	uv -= Reflect(uv, (angle)*PI);
	angle = .12;
	// 2+2=4
	uv -= Reflect(uv, (angle)*PI);
	angle = -1.13;
	//+2=6
	uv -= Reflect(uv, (angle)*PI);
	angle = .12;
	//+2=8
	uv -= Reflect(uv, (angle)*PI);
	//uv.y += sin(uv.x*8.-time*3.)*.2;//(sin(time)*.2+.2);
	uv.y += pow(fract(1.-uv.x+time),3.);
	float d = length(uv - vec2(clamp(uv.x, -1., 2.), 0));
	float dist = .5*max(0.,uv.x);
	float blur = .1;//remap(-1.,2.,.1,.25,uv.x);
	float line = smoothstep(dist,dist*blur, d);


float L = 4.;
uv.y=abs(uv.y);
for (float j = 1.;j<L;++j){
uv.x-=.5;
for (float I = 0.;I<2.;++I){
	uv.y-=2./8.;
	//uv.y += sin(uv.x*(8.)-time*2.)*.2;//(sin(time)*.2+.2);
	uv.y += pow(fract((1.-uv.x)/2.),3.);
	//reverse sin waves
	//float a = pow(1.14*fract(time/8.), 4.);
	//float b = (-8.*(fract(time/8.)))+8.;
	//uv -= reflect(uv,((min(a,b)))* PI);
	uv -= Reflect(uv,(sin(time/8.)*.3+.3)* PI);
	dist = .5*max(0.,uv.x);
	blur =.1;//remap(-1.,2.,.1,.25,uv.x);
	d = length(uv - vec2(clamp(uv.x, -1., 2.), 0));
	line += smoothstep(dist,dist*blur, d);
	}
}


col += mod(line, 2.);

col.rg += uv;

	//uv *= 2.;


	//col = texture2D(tex, uv/2.).rgb;
	col *= palette(uv.g);//mod(palette(line),2.);
    float pat = pattern(uv2);

    vec3 color = palette(pat);
	vec3 from=vec3(1.,.5,0.5)*col;



	mainVR(fragColor, fragCoord, from, dir);	
    fragColor+=vec4(color*0.5*col,1.);
}
